catalog_script_client.script:
function onLoad() {
    aplicarMascaraPercentual('v_porcentagem_de_comprometimento_de_rcl');
    aplicarMascaraPercentual('v_porcentagem_do_limite_prudencial_de_rcl');
    aplicarMascaraPercentual('v_porcentagem_de_limite_de_alerta_de_rcl');
    aplicarMascaraPercentual('v_porcentagem_do_limite_maximo_de_rcl');
    aplicarMascaraPercentual('v_comprometimento_executivo');
    aplicarMascaraPercentual('v_limite_de_alerta_executivo');
    aplicarMascaraPercentual('v_variacao_despesa_liquida_pessoal_executivo');
    aplicarMascaraPercentual('v_variacao_despesa_liquida_pessoal_consolidado');
}

function aplicarMascaraPercentual(variableName) {
    var field = g_form.getControl(variableName);
    if (!field) return;

    let rawValue = '';

    field.addEventListener('input', function () {
        rawValue = this.value.replace(/\D/g, '');

        if (rawValue === '') {
            this.value = '';
            return;
        }

        let number = parseFloat(rawValue) / 100;

        this.value = number.toLocaleString('pt-BR', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        }) + '%';
    });
}
